script:
app.beginUndoGroup("Glitch Time Stutter");
var comp = app.project.activeItem;
if (!(comp instanceof CompItem)) throw new Error("Open a composition first.");
if (comp.selectedLayers.length < 1) throw new Error("Select at least one layer.");
for (var i = 0; i < comp.selectedLayers.length; i++) {
  var layer = comp.selectedLayers[i];
  var effects = layer.property("ADBE Effect Parade");
  var stutter = effects.addProperty("ADBE Slider Control");
  stutter.name = "Stutter FPS";
  stutter.property(1).setValue(8);
  var posterize = effects.addProperty("ADBE Posterize Time");
  posterize.property("ADBE Posterize Time-0001").expression = 'effect("Stutter FPS")("Slider")';
  var echo = effects.addProperty("ADBE Echo");
  echo.property("ADBE Echo-0001").setValue(-0.05);
  echo.property("ADBE Echo-0002").setValue(4);
  echo.property("ADBE Echo-0003").setValue(1);
  echo.property("ADBE Echo-0004").setValue(0.6);
  echo.property("ADBE Echo-0005").setValue(4);
}
app.endUndoGroup();
